"""Fields the workflow already knows are built in code, not generated by the LLM.

Cost Agent: the LLM writes only relative_cost_breakdown, optimizations and
trade_offs (CostInsights); the range and drivers come from the estimator.

Final Report: the LLM writes only the synthesized fields (ReportSynthesis);
requirements, services, data flow, cost and critic summaries are built from
the workflow data, and open_recommendations stays deterministic. The public
CostAnalysis / FinalReport schemas (and so the API) are unchanged. No LLM.
"""

from __future__ import annotations

from langchain_core.utils.function_calling import convert_to_openai_tool

from agents import cost as cost_agent
from agents import llm as llm_module
from agents import report as report_agent
from api.schemas import ArchitectureResponse
from graph.state import MAX_REVISIONS
from models.schemas import (
    AWSService,
    CostAnalysis,
    CostInsights,
    CriticReview,
    FinalReport,
    ReportSynthesis,
)
from tools.cost_estimator import estimate_cost

from .conftest import (
    make_architecture,
    make_cost_analysis,
    make_cost_insights,
    make_critic_review,
    make_report_synthesis,
    make_requirements,
)
from .test_resilience import _base_state

BUILT = ("requirements_summary", "aws_services_summary", "data_flow_summary", "cost_summary", "critic_findings_summary")
SYNTHESIZED = (
    "executive_summary",
    "architecture_overview",
    "scalability_strategy",
    "high_availability_strategy",
    "security_summary",
    "reliability_summary",
    "observability_summary",
    "bottlenecks",
    "trade_offs",
    "final_recommendations",
)


def _llm_returns(monkeypatch, result) -> list[tuple[type, str]]:
    calls: list[tuple[type, str]] = []
    monkeypatch.setattr(llm_module, "get_llm", lambda temperature=0.2, max_tokens=750: object())
    monkeypatch.setattr(
        llm_module, "invoke_structured", lambda llm, schema, prompt: calls.append((schema, prompt)) or result
    )
    return calls


def _tool_fields(schema) -> set[str]:
    return set(convert_to_openai_tool(schema)["function"]["parameters"]["properties"])


# ---------------------------------------------------------------------------
# Cost Agent
# ---------------------------------------------------------------------------


def test_cost_llm_no_longer_generates_the_range_or_drivers():
    assert _tool_fields(CostInsights) == {"relative_cost_breakdown", "optimizations", "trade_offs"}


def test_cost_range_and_drivers_come_from_the_estimator_unchanged(monkeypatch):
    calls = _llm_returns(monkeypatch, make_cost_insights())
    state = _base_state()

    cost = cost_agent.run(state)["cost_analysis"]

    ((schema, prompt),) = calls
    assert schema is CostInsights
    estimate = estimate_cost(state["architecture"], state["requirements"])
    assert cost.estimated_monthly_range == (
        f"${estimate.monthly_low:,} - ${estimate.monthly_high:,} per month (educational estimate)"
    )
    assert cost.major_cost_drivers == estimate.major_cost_drivers
    # The estimate is still given to the LLM as ground truth for its reasoning...
    assert f"${estimate.monthly_low:,} - ${estimate.monthly_high:,}" in prompt
    # ...but it is no longer asked to restate it.
    assert "estimated_monthly_range:" not in prompt and "major_cost_drivers:" not in prompt


def test_cost_analysis_keeps_every_llm_insight_and_its_public_shape(monkeypatch):
    insights = make_cost_insights()
    _llm_returns(monkeypatch, insights)

    cost = cost_agent.run(_base_state())["cost_analysis"]

    assert isinstance(cost, CostAnalysis)
    assert cost.relative_cost_breakdown == insights.relative_cost_breakdown
    assert cost.optimizations == insights.optimizations and cost.trade_offs == insights.trade_offs
    assert cost.disclaimer == CostAnalysis.model_fields["disclaimer"].default
    assert set(CostAnalysis.model_fields) == {
        "estimated_monthly_range",
        "major_cost_drivers",
        "relative_cost_breakdown",
        "optimizations",
        "trade_offs",
        "disclaimer",
    }


# ---------------------------------------------------------------------------
# Final Report: schema split, API unchanged
# ---------------------------------------------------------------------------


def test_report_llm_generates_only_the_synthesized_fields():
    assert _tool_fields(ReportSynthesis) == set(SYNTHESIZED)
    assert not _tool_fields(ReportSynthesis) & {*BUILT, "open_recommendations"}


def test_public_final_report_and_api_schema_are_unchanged():
    assert list(FinalReport.model_fields) == [
        "executive_summary",
        "requirements_summary",
        "architecture_overview",
        "aws_services_summary",
        "data_flow_summary",
        "scalability_strategy",
        "high_availability_strategy",
        "security_summary",
        "reliability_summary",
        "observability_summary",
        "cost_summary",
        "bottlenecks",
        "trade_offs",
        "critic_findings_summary",
        "final_recommendations",
        "open_recommendations",
    ]
    api_schema = ArchitectureResponse.model_json_schema()
    report_props = api_schema["$defs"]["FinalReport"]["properties"]
    assert set(BUILT) | set(SYNTHESIZED) <= set(report_props)
    cost_props = api_schema["$defs"]["CostAnalysis"]["properties"]
    assert {"estimated_monthly_range", "major_cost_drivers"} <= set(cost_props)


def test_report_prompt_no_longer_asks_for_the_built_fields(monkeypatch):
    calls = _llm_returns(monkeypatch, make_report_synthesis())
    state = _base_state(critic_review=make_critic_review(approved=False), revision_count=MAX_REVISIONS)

    report_agent.run(state)

    ((schema, prompt),) = calls
    assert schema is ReportSynthesis
    field_list = prompt.split("Write the final report with these fields")[1].split("Hard size limits")[0]
    for name in BUILT:
        assert f"- {name}:" not in field_list
    for name in SYNTHESIZED:
        assert f"- {name}:" in field_list
    assert "critic_findings_summary" not in prompt  # incl. the max-revisions note
    # The analytical inputs are all still there.
    for section in ("Compute Analysis:", "Cost Analysis:", "Critic Review:", "Verified facts about the final"):
        assert section in prompt


# ---------------------------------------------------------------------------
# The built fields
# ---------------------------------------------------------------------------


def _run_report(monkeypatch, **state_overrides):
    synthesis = make_report_synthesis()
    _llm_returns(monkeypatch, synthesis)
    result = report_agent.run(_base_state(**state_overrides))
    return result["final_report"], synthesis


def test_synthesized_fields_pass_through_and_built_fields_are_filled(monkeypatch):
    report, synthesis = _run_report(monkeypatch, critic_review=make_critic_review(approved=True))

    for name in SYNTHESIZED:
        assert getattr(report, name) == getattr(synthesis, name)
    for name in BUILT:
        assert getattr(report, name).strip()


def test_requirements_summary_uses_the_stated_requirements(monkeypatch):
    requirements = make_requirements(explicit_requirements=["Supports 500,000 concurrent users", "Requires PCI-DSS."])
    report, _ = _run_report(monkeypatch, requirements=requirements, critic_review=make_critic_review(approved=True))
    assert report.requirements_summary == (
        "e-commerce platform: Supports 500,000 concurrent users; Requires PCI-DSS."
    )

    # Older requirements without explicit_requirements: the key figures instead.
    assert report_agent._requirements_summary(make_requirements(explicit_requirements=[])) == (
        "e-commerce platform for 2 million registered users, 500,000 concurrent. "
        "99.99% uptime, high availability required"
    )


def test_services_and_data_flow_come_from_the_final_design(monkeypatch):
    report, _ = _run_report(monkeypatch, critic_review=make_critic_review(approved=True))
    architecture = make_architecture()

    for service in architecture.services:
        assert service.name in report.aws_services_summary
    assert report.aws_services_summary.startswith("Services: Application Load Balancer (Distribute traffic")
    assert report.data_flow_summary == "User -> ALB; ALB -> ECS"


def test_long_service_purposes_are_truncated():
    long_purpose = AWSService(name="Amazon S3", category="Storage", purpose="x" * 200, justification="j")
    text = report_agent._aws_services_summary(make_architecture(services=[long_purpose]))
    assert len(text) < 100


def test_cost_summary_quotes_the_estimator_and_the_first_optimization(monkeypatch):
    report, _ = _run_report(monkeypatch, critic_review=make_critic_review(approved=True))
    cost = make_cost_analysis()
    assert report.cost_summary == (
        f"{cost.estimated_monthly_range}; major cost drivers: Compute, Database. "
        "Recommended first optimization: Use reserved instances for baseline compute load."
    )


def test_critic_summary_for_an_approved_design(monkeypatch):
    report, _ = _run_report(monkeypatch, critic_review=make_critic_review(approved=True), revision_count=1)
    assert report.critic_findings_summary == "Critic score 92/100 (approved) after 1 revision cycle."


def test_critic_summary_when_max_revisions_were_reached(monkeypatch):
    review = CriticReview(
        approved=False,
        score=68,
        issues=[
            {"issue": "Fargate cold starts.", "severity": "high", "category": "scalability"},
            {"issue": "Redis not multi-AZ.", "severity": "high", "category": "Reliability"},
            {"issue": "No IAM roles.", "severity": "medium", "category": "security"},
        ],
        required_changes=["Pre-warm Fargate capacity."],
    )
    report, _ = _run_report(
        monkeypatch, critic_review=review, revision_count=MAX_REVISIONS, implemented_changes=["v2: a", "v3: b"]
    )
    assert report.critic_findings_summary == (
        f"Critic score 68/100 (not approved) after {MAX_REVISIONS} revision cycles; the maximum of "
        f"{MAX_REVISIONS} was reached. 2 verified changes were made during revision. It raised 3 issues "
        "(2 high, 1 medium) in scalability, reliability, security. Its required changes remain open; "
        "see open_recommendations."
    )


# ---------------------------------------------------------------------------
# Claim verification and fallback still work
# ---------------------------------------------------------------------------


def test_claim_verification_still_checks_the_synthesized_fields(monkeypatch):
    synthesis = make_report_synthesis().model_copy(
        update={"architecture_overview": "ALB, ECS and Aurora. DynamoDB added for sessions.", "bottlenecks": [
            "Aurora write throughput at peak", "DynamoDB hot partitions"]}
    )
    _llm_returns(monkeypatch, synthesis)

    report = report_agent.run(_base_state(critic_review=make_critic_review(approved=True)))["final_report"]

    assert report.architecture_overview == "ALB, ECS and Aurora."
    assert report.bottlenecks == ["Aurora write throughput at peak"]
    assert "DynamoDB" not in report.aws_services_summary


def test_built_fields_describe_only_the_design_so_they_survive_verification(monkeypatch, caplog):
    with caplog.at_level("INFO"):
        report, _ = _run_report(monkeypatch, critic_review=make_critic_review(approved=False))
    event = next(r.event_fields for r in caplog.records if getattr(r, "event_fields", {}).get("event") == "report_claims_checked")
    assert event["fields_changed"] == 0  # nothing built from the data needed removing
    assert report.aws_services_summary.startswith("Services: ")


def test_fallback_report_uses_the_same_built_fields(monkeypatch):
    def failing(llm, schema, prompt):
        raise llm_module.LLMInvocationError("x")

    monkeypatch.setattr(llm_module, "get_llm", lambda temperature=0.2, max_tokens=750: object())
    monkeypatch.setattr(llm_module, "invoke_structured", failing)
    state = _base_state(critic_review=make_critic_review(approved=True))
    fallback = report_agent.run(state)

    synthesized, _ = _run_report(monkeypatch, critic_review=make_critic_review(approved=True))

    report = fallback["final_report"]
    assert "failed" in fallback["execution_trace"][0]["action"].lower()
    for name in BUILT:
        assert getattr(report, name) == getattr(synthesized, name)
    assert make_architecture().summary in report.executive_summary  # fallback's own text, unchanged
    assert report.bottlenecks == ["Report synthesis failed -- review the execution trace for full analysis detail."]


# ---------------------------------------------------------------------------
# open_recommendations keeps the final review's required changes, approved or not
# ---------------------------------------------------------------------------


def test_approved_review_keeps_its_non_blocking_required_changes(monkeypatch):
    # An approval can still list changes (e.g. for a MEDIUM finding).
    review = CriticReview(
        approved=True,
        score=84,
        issues=[{"issue": "No caching layer for catalog reads.", "severity": "medium", "category": "performance"}],
        required_changes=["Add ElastiCache in front of catalog reads."],
    )

    report, _ = _run_report(monkeypatch, critic_review=review, critic_history=[review])

    assert report.open_recommendations == ["Add ElastiCache in front of catalog reads."]
    assert "(approved)" in report.critic_findings_summary  # approval itself is unchanged


def test_rejected_review_keeps_its_required_changes(monkeypatch):
    review = make_critic_review(approved=False)

    report, _ = _run_report(monkeypatch, critic_review=review, critic_history=[review])

    assert report.open_recommendations == review.required_changes


def test_approved_review_without_required_changes_has_no_open_recommendations(monkeypatch):
    review = make_critic_review(approved=True)
    assert review.required_changes == []

    report, _ = _run_report(monkeypatch, critic_review=review, critic_history=[review])

    assert report.open_recommendations == []


def test_open_recommendations_keep_dedup_order_and_limit():
    review = CriticReview(approved=True, score=85, required_changes=[f"Change {n}." for n in range(10)] + ["Change 0."])

    items = report_agent._open_recommendations(make_architecture(), review, [review])

    assert items == [f"Change {n}." for n in range(report_agent._MAX_OPEN_RECOMMENDATIONS)]
